// La anti-repetición (misma alerta en 10 min) la hace Enviar_Alerta consultando alertas_auditoria.
// (En N8N 2.x la memoria del flujo no se conserva entre ejecuciones de flujos publicados.)
function primeraVez() { return true; }

// H3: el usuario de solo lectura agente_ia recibió permisos de escritura
const filas = $input.all().map(i => i.json).filter(r => r.tabla);
if (filas.length === 0) return [];
const privs = [...new Set(filas.map(r => r.priv))].join(', ');
const tablas = [...new Set(filas.map(r => r.tabla))];
if (!primeraVez('H3:' + privs + ':' + tablas.length)) return [];
return [{ json: {
  codigo: 'H3',
  severidad: 'CRÍTICA',
  tipo: 'Escalada de privilegios en agente_ia',
  tabla: tablas.slice(0, 5).join(', ') + (tablas.length > 5 ? ` (+${tablas.length - 5} más)` : ''),
  detalle: `agente_ia (solo lectura) tiene ahora: ${privs} en ${tablas.length} tabla(s)`,
  query: 'GRANT ... TO agente_ia',
  usuario: 'agente_ia',
  accion: 'Revocar de inmediato: REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON ALL TABLES IN SCHEMA public FROM agente_ia;'
}}];
